    acceptInteraction: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                interactionId: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Interação aceita */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "id": "346da57c-ddca-4ed8-844e-3632de47f125",
                     *       "status": "ACCEPTED"
                     *     }
                     */
                    "application/json": components["schemas"]["AcceptedInteraction"];
                };
            };
            /** @description Sessão ausente, expirada ou inválida */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "type": "about:blank",
                     *       "title": "Unauthorized",
                     *       "status": 401,
                     *       "code": "SESSION_REQUIRED"
                     *     }
                     */
                    "application/problem+json": components["schemas"]["ApiProblem"];
                };
            };
            /** @description A sessão existe e o ator não tem permissão para a ação */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "type": "about:blank",
                     *       "title": "Forbidden",
                     *       "status": 403,
                     *       "code": "ACTION_FORBIDDEN"
                     *     }
                     */
                    "application/problem+json": components["schemas"]["ApiProblem"];
                };
            };
            /** @description Interação inexistente ou invisível para o ator */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "type": "about:blank",
                     *       "title": "Not Found",
                     *       "status": 404,
                     *       "code": "INTERACTION_NOT_FOUND"
                     *     }
                     */
                    "application/problem+json": components["schemas"]["ApiProblem"];
                };
            };
            /** @description Conflito com o estado atual da interação ou da vaga */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "type": "about:blank",
                     *       "title": "Conflict",
                     *       "status": 409,
                     *       "code": "SLOT_UNAVAILABLE"
                     *     }
                     */
                    "application/problem+json": components["schemas"]["ApiProblem"];
                };
            };
            /** @description A solicitação é válida, mas as regras de elegibilidade impedem o aceite */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "type": "about:blank",
                     *       "title": "Unprocessable Content",
                     *       "status": 422,
                     *       "code": "INCOMPATIBLE_REQUIREMENTS"
                     *     }
                     */
                    "application/problem+json": components["schemas"]["ApiProblem"];
                };
            };
        };
    };
